CREATE TABLE IF NOT EXISTS client (
    client_code VARCHAR(20) PRIMARY KEY,
    order_name VARCHAR(300) NOT NULL,
    order_eng_name VARCHAR(300),
    business_no VARCHAR(20),
    corp_no VARCHAR(20),
    order_name_long VARCHAR(300),
    owner VARCHAR(100),
    business_sectors VARCHAR(100),
    business_items VARCHAR(100),
    order_class VARCHAR(20),
    zip_code VARCHAR(20),
    addr1 VARCHAR(500),
    addr2 VARCHAR(500),
    remark VARCHAR(1000),
    company_type VARCHAR(20),
    homeurl VARCHAR(500),
    otype VARCHAR(20),
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    created_id VARCHAR(100),
    last_changed_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    last_changed_id VARCHAR(100)
);

CREATE INDEX IF NOT EXISTS ix_client_order_name ON client (order_name);
CREATE INDEX IF NOT EXISTS ix_client_order_class ON client (order_class);
CREATE INDEX IF NOT EXISTS ix_client_company_type ON client (company_type);

